// Page 4 inside the shared canvas: the requirement pins lift off today's car and stand on a ring around it as a
// priority skyline. One column per requirement on the car line, grouped by vehicle domain; its HEIGHT is the target's
// score in the selected market, its MARK the band (Must solid, Should outlined, Could a thin line), its hue the domain.
// Two faint planes at the band thresholds (Should 45, Must 60). Switching market morphs the heights, so the PM sees
// where markets disagree (D-011). At JUL a ghost tick keeps JAN's height and movers pulse once. Bundles join their
// bases with a faint chord; two Musts that must be chosen jointly carry a dashed white arc labelled with the resource.
// A PM-confirmed band is the PM's position: the one blue mark, a dot with its wash at the column's base.
// Rendered inside DefinitionLayer's car group (same frame, same rise); leaving runs the move back onto the car.
import { memo, useCallback, useEffect, useMemo, useRef, useState, type MutableRefObject } from "react";
import { useFrame, useThree } from "@react-three/fiber";
import { Html, Line } from "@react-three/drei";
import * as THREE from "three";
import type { Band, Target } from "@/lib/prioritize";
import type { ZoneDef } from "@/three/frame";
import { zoneToWorld, type CarFrame, type Vec3 } from "@/three/frame";
import { useCheckpoint } from "@/state/checkpoint";
import type { NavInput } from "../scan/navigate";
import { domainColor } from "../definition/data";
import { glide } from "../definition/StageLayer";
import { useView } from "../definition/store";
import { bandsAt, isBlocked, marketsOf, openProposals, parseFlags, pmBand, shownBand, usePrioritize } from "./data";
import { getP, selectTarget, setP, useP } from "./store";

export const RING_R = 2.45;          // world units; the car's half-length is ≈ 1.73
export const H_MAX = 2.0;            // height of a score of 100
const LIFT_S = 2.3, STAGGER = 0.38, WAIT = 0.25;
const INK = "#f2f4f7", SWEEP_HI = "#4d94ff";
const W = { Must: 0.064, Should: 0.064, Could: 0.016 };

const clamp01 = (x: number) => Math.max(0, Math.min(1, x));
const smooth = (a: number, b: number, x: number) => { const t = clamp01((x - a) / (b - a)); return t * t * (3 - 2 * t); };
const easeIO = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
const easeOut = (t: number) => 1 - Math.pow(1 - t, 3);
const hOf = (score: number) => (Math.max(0, Math.min(100, score)) / 100) * H_MAX;
const DOMAIN_ORDER = ["exterior", "interior", "powertrain", "chassis", "assist", "digital", "variants", "quality"];

type Orbit = { target: THREE.Vector3; update: () => void };

interface Col { key: string; title: string; domain: string; zone: string | null; angle: number; slot: Vec3; from: Vec3; order: number }

/* unit geometries, shared: base at y = 0, height 1 */
const BOX = new THREE.BoxGeometry(1, 1, 1).translate(0, 0.5, 0);
const EDGES = new THREE.EdgesGeometry(BOX);
const DOT = new THREE.SphereGeometry(1, 16, 12);
const DISC = new THREE.CircleGeometry(1, 32).rotateX(-Math.PI / 2);
const HALO = new THREE.RingGeometry(0.62, 1, 40).rotateX(-Math.PI / 2);
const SLOT = new THREE.RingGeometry(0.7, 1, 24).rotateX(-Math.PI / 2);

export function Skyline({ active, frame, zones, carScale, reduced, nav, sweepId }: {
  active: boolean; frame: CarFrame; zones: Record<string, ZoneDef>; carScale: number; reduced: boolean;
  nav?: MutableRefObject<NavInput>; sweepId: number;
}) {
  const pd = usePrioritize();
  const { data } = pd;
  const { position } = useCheckpoint();
  const line = useView((s) => s.line);
  const markets = useMemo(() => marketsOf(data, line), [data, line]);
  const stored = useP((s) => s.market[line]);
  const market = stored && markets.includes(stored) ? stored : markets[0] ?? "";
  const selected = useP((s) => s.selected);
  const hover = useP((s) => s.hover);
  const bundle = useP((s) => s.bundle);
  const flat = useP((s) => s.view === "matrix");   // the matrix is in front: the skyline steps back
  useP((s) => s.pending);
  useP((s) => s.pendingProposals);
  const at = bandsAt(data);

  /* the ring: every requirement on this line (any market) keeps its slot, so switching market only moves heights */
  const cols = useMemo<Col[]>(() => {
    const by = new Map<string, { t: Target; max: number }>();
    for (const t of data.targets) if (t.line === line) {
      const cur = by.get(t.key);
      if (!cur || t.score > cur.max) by.set(t.key, { t, max: Math.max(t.score, cur?.max ?? 0) });
    }
    const list = [...by.values()].sort((a, b) => (DOMAIN_ORDER.indexOf(a.t.domain) + 99) % 99 - (DOMAIN_ORDER.indexOf(b.t.domain) + 99) % 99 || b.max - a.max);
    const groups = new Set(list.map((x) => x.t.domain)).size;
    const GAP = 1.4;
    const units = list.length + groups * GAP;
    const step = (Math.PI * 2) / Math.max(units, 8);
    let u = GAP / 2, prev = "";
    // start at the back so the first domain group sits at the far left and the ring reads clockwise toward the camera
    const a0 = Math.PI * 0.62;
    return list.map(({ t }, i) => {
      if (prev && t.domain !== prev) u += GAP;
      prev = t.domain;
      const angle = a0 + (u + 0.5) * step;
      u += 1;
      const z = t.zones.find((k) => zones[k]) ?? null;
      const from = z ? zoneToWorld(zones[z].pos, frame).map((v) => v * carScale) as Vec3 : [0, 0.5, 0] as Vec3;
      return { key: t.key, title: t.title, domain: t.domain, zone: z, angle, order: i,
               slot: [RING_R * Math.cos(angle), 0, RING_R * Math.sin(angle)] as Vec3, from };
    });
  }, [data.targets, line, zones, frame, carScale]);
  const colOf = useMemo(() => new Map(cols.map((c) => [c.key, c])), [cols]);
  const inMarket = useMemo(() => new Map(data.targets.filter((t) => t.line === line && t.market === market).map((t) => [t.key, t])), [data.targets, line, market]);
  const proposals = useMemo(() => new Map(openProposals(data).filter((p) => p.line === line && p.market === market).map((p) => [p.key, p])), [data, line, market]); // eslint-disable-line react-hooks/exhaustive-deps

  /* domain group labels on the ground, outside the ring */
  const groups = useMemo(() => {
    const m = new Map<string, Col[]>();
    for (const c of cols) m.set(c.domain, [...(m.get(c.domain) ?? []), c]);
    return [...m].map(([d, cs]) => {
      const a = (cs[0].angle + cs[cs.length - 1].angle) / 2;
      return { d, n: cs.filter((c) => inMarket.has(c.key)).length, at: [(RING_R + 0.62) * Math.cos(a), 0, (RING_R + 0.62) * Math.sin(a)] as Vec3 };
    });
  }, [cols, inMarket]);

  /* the lift: one scalar, staggered per column; reversed it lowers the columns back onto the car */
  const t = useRef(0);
  const wait = useRef(WAIT);
  const [present, setPresent] = useState(active);
  useEffect(() => { if (active) { setPresent(true); wait.current = reduced ? 0 : WAIT; } }, [active, reduced]);
  const heights = useRef(new Map<string, number>());
  const refs = useRef(new Map<string, ColRefs>());
  const planes = useRef<THREE.Group>(null);
  const ground = useRef<THREE.Group>(null);
  const overlay = useRef<THREE.Group>(null);
  const chords = useRef<THREE.Group>(null);
  // DOM labels that fade with the planes (fade) or appear once every column has landed (late)
  const fade = useRef(new Set<HTMLElement>());
  const late = useRef(new Set<HTMLElement>());
  const fadeRef = useCallback((el: HTMLElement | null) => { if (el) fade.current.add(el); }, []);
  const lateRef = useCallback((el: HTMLElement | null) => { if (el) late.current.add(el); }, []);
  const v = useMemo(() => ({ m: new THREE.Vector3(), a: new THREE.Vector3(), b: new THREE.Vector3(), c: new THREE.Vector3(), q: new THREE.QuadraticBezierCurve3() }), []);
  useFrame((_, dt) => {
    const goal = active ? 1 : 0;
    if (active && wait.current > 0) wait.current -= dt;
    else if (t.current !== goal) {
      const k = reduced ? 1 : dt / LIFT_S;
      t.current = goal > t.current ? Math.min(1, t.current + k) : Math.max(0, t.current - k * 1.25);
    }
    const out = t.current > 0;
    if (out !== getP().out) setP({ out });
    if (!active && t.current === 0 && present) setPresent(false);
    const T = t.current;
    const n = Math.max(1, cols.length);
    const morph = reduced ? 1 : 1 - Math.exp(-dt * 4.5);
    for (const c of cols) {
      const r = refs.current.get(c.key);
      if (!r?.group) continue;
      const tg = inMarket.get(c.key);
      const goalH = tg ? hOf(tg.score) : 0;
      const h0 = heights.current.get(c.key) ?? goalH;
      const h = Math.abs(goalH - h0) < 0.0005 ? goalH : h0 + (goalH - h0) * morph;
      heights.current.set(c.key, h);
      const d = (c.order / n) * STAGGER;
      const ti = clamp01((T - d) / (1 - STAGGER));
      const fly = easeIO(clamp01(ti / 0.55));
      const grow = smooth(0.5, 1, ti);
      v.a.set(...c.from); v.c.set(...c.slot);
      v.b.lerpVectors(v.a, v.c, 0.5); v.b.y = Math.max(v.a.y, 0) + 0.85;
      v.q.v0.copy(v.a); v.q.v1.copy(v.b); v.q.v2.copy(v.c);
      v.q.getPoint(fly, v.m);
      r.group.position.copy(v.m);
      r.group.visible = T > 0.001;
      const shownH = Math.max(0.0001, h * grow);
      if (r.scale) r.scale.scale.y = shownH;
      if (r.cap) r.cap.position.y = shownH;
      if (r.pin) { const s = (1 - grow) * 0.05; r.pin.visible = s > 0.002; r.pin.scale.setScalar(Math.max(0.0001, s)); }
      if (r.base) r.base.visible = grow > 0.6;
      if (r.ghost) r.ghost.visible = grow > 0.98;
      if (r.label) { const o = smooth(0.85, 1, ti); r.label.style.opacity = o.toFixed(3); r.label.style.visibility = o > 0.02 ? "" : "hidden"; }
    }
    const show = smooth(0.55, 1, T);
    if (planes.current) { planes.current.visible = show > 0.01; planes.current.position.y = 0; planes.current.scale.setScalar(0.92 + 0.08 * show); setOpacity(planes.current, show); }
    if (ground.current) { ground.current.visible = show > 0.01; setOpacity(ground.current, show); }
    if (overlay.current) overlay.current.visible = T >= 0.999;
    if (chords.current) chords.current.visible = T >= 0.9;
    for (const el of fade.current) { if (!el.isConnected) { fade.current.delete(el); continue; } el.style.opacity = show.toFixed(3); el.style.visibility = show > 0.02 ? "" : "hidden"; }
    for (const el of late.current) { if (!el.isConnected) { late.current.delete(el); continue; } el.style.visibility = T >= 0.999 ? "" : "hidden"; }
  });

  useSkylineCamera(active, reduced, nav);
  useEffect(() => () => { setP({ out: false }); document.body.style.cursor = ""; }, []);

  /* bundles present in this market: chords between their bases, through the inside of the ring */
  const bundleChords = useMemo(() => {
    const out: { id: string; pts: THREE.Vector3[]; keys: string[] }[] = [];
    for (const b of data.bundles) {
      const members = b.keys.filter((k) => inMarket.has(k) && colOf.has(k)).map((k) => colOf.get(k)!).sort((a, c) => a.angle - c.angle);
      if (members.length < 2) continue;
      const pts: THREE.Vector3[] = [];
      for (let i = 0; i < members.length - 1; i++) {
        const A = new THREE.Vector3(...members[i].slot), C = new THREE.Vector3(...members[i + 1].slot);
        const B = A.clone().lerp(C, 0.5).multiplyScalar(0.62);
        const seg = new THREE.QuadraticBezierCurve3(A, B, C).getPoints(28);
        pts.push(...(i ? seg.slice(1) : seg));
      }
      pts.forEach((p) => { p.y = 0.006; });
      out.push({ id: b.id, pts, keys: members.map((m) => m.key) });
    }
    return out;
  }, [data.bundles, inMarket, colOf]);

  /* two Musts to choose jointly: a dashed arc between their tops, the shared resource at the apex */
  const joint = useMemo(() => {
    const seen = new Set<string>();
    const out: { id: string; a: string; b: string; via: string; pts: THREE.Vector3[]; apex: THREE.Vector3 }[] = [];
    for (const tg of inMarket.values()) for (const f of parseFlags(tg)) {
      if (f.kind !== "choose_jointly" || !f.partner) continue;
      const id = [tg.key, f.partner].sort().join("~");
      const other = inMarket.get(f.partner);
      if (seen.has(id) || !other || !colOf.has(tg.key) || !colOf.has(f.partner)) continue;
      seen.add(id);
      const A = new THREE.Vector3(...colOf.get(tg.key)!.slot).setY(hOf(tg.score) + 0.05);
      const C = new THREE.Vector3(...colOf.get(f.partner)!.slot).setY(hOf(other.score) + 0.05);
      const B = A.clone().lerp(C, 0.5).multiplyScalar(0.78); B.y = Math.max(A.y, C.y) + 0.55 + A.distanceTo(C) * 0.12;
      const q = new THREE.QuadraticBezierCurve3(A, B, C);
      out.push({ id, a: tg.key, b: f.partner, via: f.via ?? "", pts: q.getPoints(40), apex: q.getPoint(0.5) });
    }
    return out;
  }, [inMarket, colOf]);

  const register = useCollisions();
  const onRef = useCallback((key: string, r: ColRefs) => { refs.current.set(key, r); }, []);

  if (!present) return null;
  const selCol = selected && inMarket.has(selected) ? selected : null;
  const bundleKeys = new Set(data.bundles.find((b) => b.id === bundle)?.keys ?? []);
  const focusBundle = selCol ? inMarket.get(selCol)?.bundle_id ?? null : null;
  const facing = new THREE.Vector3(0.67, 0, -0.74);

  return (
    <group>
      {/* the band thresholds: two faint planes over the ring */}
      <group ref={planes}>
        <Plane y={hOf(at.Should)} label={`Should · ${at.Should}`} strength={0.09} facing={facing} labelRef={fadeRef} />
        <Plane y={hOf(at.Must)} label={`Must · ${at.Must}`} strength={0.14} facing={facing} labelRef={fadeRef} />
      </group>
      {/* the ground ring and the domain groups */}
      <group ref={ground}>
        <RingLine r={RING_R} y={0.003} opacity={0.12} />
        {groups.map((g) => (
          <Html key={g.d} position={g.at} center zIndexRange={[12, 10]}>
            <span ref={fadeRef} className="psky-group" style={{ ["--c" as string]: domainColor(g.d) }}><i aria-hidden />{DOMAIN_LABEL[g.d] ?? g.d}<b>{g.n}</b></span>
          </Html>
        ))}
      </group>
      <group ref={chords}>
        {bundleChords.map((b) => {
          const hot = bundle === b.id || focusBundle === b.id || (!!hover && b.keys.includes(hover));
          return <Line key={b.id} points={b.pts} color={INK} lineWidth={hot ? 1.6 : 1} transparent opacity={hot ? 0.62 : 0.16} depthWrite={false} />;
        })}
      </group>
      {cols.map((c) => {
        const tg = inMarket.get(c.key) ?? null;
        const band = tg ? shownBand(tg) : null;
        const on = selCol === c.key;
        const hot = on || hover === c.key;
        const dim = flat || (bundleKeys.size > 0 && !bundleKeys.has(c.key)) || (!!selCol && !on);
        const delta = tg?.prev && position > 1 ? tg.score - tg.prev.score : 0;
        const moved = !!tg?.prev && position > 1 && (Math.abs(delta) >= 3 || tg.prev.band !== tg.band);
        return (
          <Column key={c.key} c={c} t={tg} band={band} hot={hot} on={on} dim={dim} pm={tg ? pmBand(tg) : null} blocked={tg ? isBlocked(tg) : false}
                  proposal={proposals.get(c.key)?.proposed_band ?? null} prevH={tg?.prev && position > 1 && Math.abs(delta) >= 1 ? hOf(tg.prev.score) : null}
                  pulse={moved ? `${sweepId}:${market}` : null} delta={delta} register={register} onRef={onRef} />
        );
      })}
      <group ref={overlay}>
        {joint.map((j) => {
          const hot = selCol === j.a || selCol === j.b || hover === j.a || hover === j.b;
          return (
            <group key={j.id}>
              <Line points={j.pts} color={INK} lineWidth={hot ? 1.8 : 1.3} dashed dashSize={0.07} gapSize={0.06} transparent opacity={hot ? 0.95 : 0.7} depthWrite={false} renderOrder={6} />
              <Html position={j.apex} center zIndexRange={[13, 11]}>
                <div ref={lateRef} className="dlink-label" data-dashed="">choose jointly · {j.via}</div>
              </Html>
            </group>
          );
        })}
      </group>
    </group>
  );
}

const DOMAIN_LABEL: Record<string, string> = {
  exterior: "Exterior", interior: "Interior & comfort", powertrain: "Powertrain & charging", chassis: "Chassis & dynamics",
  assist: "Driver assistance", digital: "Infotainment & digital", variants: "Variants & packages", quality: "Design & quality",
};

function setOpacity(g: THREE.Object3D, k: number) {
  g.traverse((o) => {
    const m = (o as THREE.Mesh).material as (THREE.Material & { opacity: number; userData: { base?: number } }) | undefined;
    if (!m || Array.isArray(m)) return;
    if (m.userData.base == null) m.userData.base = m.opacity;
    m.opacity = m.userData.base * k;
  });
}

/* ------------------------------------------------------------------------------------------- planes */
function RingLine({ r, y, opacity }: { r: number; y: number; opacity: number }) {
  const geom = useMemo(() => {
    const pts: THREE.Vector3[] = [];
    for (let i = 0; i <= 180; i++) { const a = (i / 180) * Math.PI * 2; pts.push(new THREE.Vector3(Math.cos(a) * r, y, Math.sin(a) * r)); }
    return new THREE.BufferGeometry().setFromPoints(pts);
  }, [r, y]);
  return <lineLoop geometry={geom}><lineBasicMaterial color="#ffffff" transparent opacity={opacity} depthWrite={false} /></lineLoop>;
}

function Plane({ y, label, strength, facing, labelRef }: { y: number; label: string; strength: number; facing: THREE.Vector3; labelRef: (el: HTMLElement | null) => void }) {
  const annulus = useMemo(() => new THREE.RingGeometry(RING_R - 0.34, RING_R + 0.34, 120).rotateX(-Math.PI / 2), []);
  const at: Vec3 = [facing.x * (RING_R + 0.5), y, facing.z * (RING_R + 0.5)];
  return (
    <group>
      <mesh geometry={annulus} position={[0, y, 0]} renderOrder={1}>
        <meshBasicMaterial color="#ffffff" transparent opacity={strength * 0.28} depthWrite={false} side={THREE.DoubleSide} />
      </mesh>
      <RingLine r={RING_R} y={y} opacity={strength} />
      <RingLine r={RING_R + 0.34} y={y} opacity={strength * 0.45} />
      <Html position={at} center zIndexRange={[11, 10]}>
        <span ref={labelRef} className="psky-plane">{label}</span>
      </Html>
    </group>
  );
}

/* ------------------------------------------------------------------------------------------- columns */
interface ColRefs { group: THREE.Group | null; scale: THREE.Group | null; cap: THREE.Group | null; pin: THREE.Mesh | null; base: THREE.Group | null; ghost: THREE.Mesh | null; label: HTMLElement | null }

const Column = memo(function Column({ c, t, band, hot, on, dim, pm, blocked, proposal, prevH, pulse, delta, register, onRef }: {
  c: Col; t: Target | null; band: Band | null; hot: boolean; on: boolean; dim: boolean; pm: Band | null; blocked: boolean;
  proposal: Band | null; prevH: number | null; pulse: string | null; delta: number; register: Register; onRef: (k: string, r: ColRefs) => void;
}) {
  const r = useRef<ColRefs>({ group: null, scale: null, cap: null, pin: null, base: null, ghost: null, label: null });
  useEffect(() => { onRef(c.key, r.current); }, [c.key, onRef]);
  const color = hot ? INK : domainColor(c.domain);
  const k = dim ? 0.28 : 1;
  const w = band ? W[band] : W.Could;
  const enter = (e: { stopPropagation: () => void; clientX?: number; clientY?: number; nativeEvent?: PointerEvent }) => {
    e.stopPropagation();
    if (!t) return;
    const ne = e.nativeEvent;
    setP({ hover: c.key, hoverPos: ne ? { x: ne.clientX, y: ne.clientY } : null });
    document.body.style.cursor = "pointer";
  };
  const labelRef = register(c.key, on || hot ? 1e9 : t ? t.score : -1);
  return (
    <group ref={(g) => { r.current.group = g; }}>
      {/* the column, by band: Must solid, Should outlined over a faint fill, Could a thin line */}
      <group ref={(g) => { r.current.scale = g; }}>
        {band === "Must" && <mesh geometry={BOX} scale={[w, 1, w]}><meshBasicMaterial color={color} transparent opacity={0.95 * k} /></mesh>}
        {band === "Should" && (
          <>
            <mesh geometry={BOX} scale={[w, 1, w]}><meshBasicMaterial color={color} transparent opacity={0.13 * k} depthWrite={false} /></mesh>
            <lineSegments geometry={EDGES} scale={[w, 1, w]}><lineBasicMaterial color={color} transparent opacity={0.95 * k} /></lineSegments>
          </>
        )}
        {band === "Could" && <mesh geometry={BOX} scale={[w, 1, w]}><meshBasicMaterial color={color} transparent opacity={0.85 * k} /></mesh>}
        {t && (
          <mesh geometry={BOX} scale={[0.22, 1, 0.22]} onPointerOver={enter}
                onPointerMove={(e) => setP({ hoverPos: { x: e.nativeEvent.clientX, y: e.nativeEvent.clientY } })}
                onPointerOut={() => { if (getP().hover === c.key) setP({ hover: null, hoverPos: null }); document.body.style.cursor = ""; }}
                onClick={(e) => { e.stopPropagation(); selectTarget(on ? null : c.key); }}>
            <meshBasicMaterial visible={false} />
          </mesh>
        )}
      </group>
      {/* the pin in flight (domain hue), shrinking into the column as it grows */}
      <mesh ref={(m) => { r.current.pin = m; }} geometry={DOT}><meshBasicMaterial color={domainColor(c.domain)} /></mesh>
      {/* ground: the slot (hollow when this market has no target here) and the PM's position */}
      <group ref={(g) => { r.current.base = g; }}>
        <mesh geometry={SLOT} position={[0, 0.004, 0]} scale={t ? 0.05 : 0.04}><meshBasicMaterial color={t ? domainColor(c.domain) : "#868d99"} transparent opacity={t ? 0.55 * k : 0.6} depthWrite={false} /></mesh>
        {pm && (
          <>
            <mesh geometry={DISC} position={[0, 0.006, 0]} scale={0.055}><meshBasicMaterial color={SWEEP_HI} depthWrite={false} /></mesh>
            <mesh geometry={HALO} position={[0, 0.005, 0]} scale={0.12}><meshBasicMaterial color="#1c69d4" transparent opacity={0.45} depthWrite={false} /></mesh>
          </>
        )}
      </group>
      {/* JAN's height at JUL: a ghost tick */}
      {prevH != null && (
        <mesh ref={(m) => { r.current.ghost = m; }} position={[0, prevH, 0]} scale={[0.13, 0.005, 0.13]} geometry={BOX}>
          <meshBasicMaterial color={INK} transparent opacity={0.38 * k} depthWrite={false} />
        </mesh>
      )}
      {/* the top: Could's cap dot, and the score numeral */}
      <group ref={(g) => { r.current.cap = g; }}>
        {band === "Could" && <mesh geometry={DOT} scale={0.024}><meshBasicMaterial color={color} transparent opacity={k} /></mesh>}
        {t && (
          <Html position={[0, 0.07, 0]} center zIndexRange={[13, 11]}>
            <div ref={(el) => { r.current.label = el; labelRef(el); }} className="psky-cap" data-hot={hot ? "" : undefined} data-on={on ? "" : undefined}
                 data-dim={dim ? "" : undefined} data-band={band ?? undefined}>
              {pulse && <i key={pulse} className="psky-pulse" aria-hidden />}
              {blocked && <span className="psky-blocked" title="Brand fit fails: approval blocked" aria-label="blocked by brand fit" />}
              <span className="psky-num">{Math.round(t.score)}</span>
              {delta !== 0 && Math.abs(delta) >= 1 && <span className="psky-delta">{delta > 0 ? "+" : "−"}{Math.abs(Math.round(delta))}</span>}
              {proposal && <span className="psky-prop" aria-label={`AI proposes ${proposal}`}>{proposal === "Must" || (proposal === "Should" && band === "Could") ? "▲" : "▼"}</span>}
            </div>
          </Html>
        )}
      </group>
    </group>
  );
});

/* ------------------------------------------------------------------------------------------- label collisions */
type Register = (key: string, prio: number) => (el: HTMLElement | null) => void;
function useCollisions(): Register {
  const labels = useRef(new Map<string, { el: HTMLElement; prio: number }>());
  const tick = useRef(0);
  const register = useCallback<Register>((key, prio) => (el) => {
    if (el) labels.current.set(key, { el, prio }); else labels.current.delete(key);
  }, []);
  useFrame(() => {
    if (tick.current++ % 6) return;
    const placed: DOMRect[] = [];
    for (const { el, prio } of [...labels.current.values()].sort((a, b) => b.prio - a.prio)) {
      const r = el.getBoundingClientRect();
      if (!r.width) continue;
      const hit = prio < 1e9 && placed.some((q) => r.left < q.right + 2 && r.right > q.left - 2 && r.top < q.bottom + 1 && r.bottom > q.top - 1);
      el.toggleAttribute("data-collide", hit);
      if (!hit) placed.push(r);
    }
  });
  return register;
}

/* ------------------------------------------------------------------------------------------- camera */
// An elevated three-quarter view of the whole ring, centred on screen; opening a priority or the panel leaves it
// where it is. The nav pad's Reset re-plans the same flight.

function useSkylineCamera(active: boolean, reduced: boolean, nav?: MutableRefObject<NavInput>) {
  const controls = useThree((s) => s.controls) as unknown as Orbit | null;
  const camera = useThree((s) => s.camera);
  const aspect = useThree((s) => s.size.width / Math.max(1, s.size.height));
  const flight = useRef<{ t0: number; fromP: THREE.Vector3; fromT: THREE.Vector3; toP: THREE.Vector3; toT: THREE.Vector3; dur: number } | null>(null);
  const lastReset = useRef(nav?.current.reset ?? 0);
  const plan = useCallback((dur = 1.6) => {
    if (!controls) return;
    const pull = aspect < 1.3 ? Math.min(2.2, Math.pow(1.3 / aspect, 0.9)) : 1;
    const tgt = new THREE.Vector3(0, 0.35, 0);
    const dir = new THREE.Vector3(0.6, 0.72, -0.72).normalize();
    const p = tgt.clone().add(dir.multiplyScalar(10.2 * pull));
    flight.current = { t0: -1, fromP: camera.position.clone(), fromT: controls.target.clone(), toP: p, toT: tgt, dur: reduced ? 0 : dur };
  }, [controls, camera, aspect, reduced]);
  useEffect(() => {
    if (!active) { flight.current = null; return; }
    plan();
  }, [active, plan]);
  useFrame(({ clock }) => {
    if (nav && nav.current.reset !== lastReset.current) { lastReset.current = nav.current.reset; if (active) plan(); }
    const f = flight.current;
    if (!f || !controls) return;
    if (f.t0 < 0) f.t0 = clock.elapsedTime;
    const p = f.dur ? Math.min(1, (clock.elapsedTime - f.t0) / f.dur) : 1;
    glide(f.fromP, f.fromT, f.toP, f.toT, easeOut(p), camera.position, controls.target);
    controls.update();
    if (p >= 1) flight.current = null;
  });
}

// Page 4 overlays at the edges of the shared canvas: car line, market and view switch with the band readout top-left;
// the ranked priorities and the target inspector behind the top-right "Priorities" pill (factor waterfall, gates,
// what-if rung, bundle, flags, history, proposal and the PM's decision); the market × requirement matrix as the 2D
// alternative; the hover card; and the Guide / Agent dock bottom-left. State lives in ./store (market, selection)
// and page 3's store (car line), so the skyline in the canvas and the overlays stay in step.
import { useEffect, useMemo, useRef, useState } from "react";
import { X } from "lucide-react";
import type { Rung } from "@/lib/definition";
import type { Band, Proposal, Target } from "@/lib/prioritize";
import { BANDS, gateResult, gateWhy } from "@/lib/prioritize";
import { Dock } from "@/components/Guide";
import { getActor } from "@/lib/api";
import { getTopPanel, setTopPanel, useTopPanel } from "@/components/topPanel";
import { useCheckpoint } from "@/state/checkpoint";
import { AgentPanel, useActivity } from "../structure/AgentPanel";
import { domainColor } from "../definition/data";
import { setView, useView } from "../definition/store";
import { DEF_STAGES } from "../definition/stages";
import type { LineName } from "@/lib/definition";
import {
  CAUSE_LABEL, CP_LABEL, bandsAt, disagreements, factorLabel, flagLabel, isBlocked, linesOf, marketsOf, openProposals, parseFlags,
  pmBand, shownBand, tid, useDecision, usePrioritize, useProposalVerdict, useTargetDetail, useWhatIf, type PrioData,
} from "./data";
import { Arrow, BandMark, GateMark } from "./marks";
import { Waterfall } from "./Waterfall";
import { PrioritizeGuide } from "./guide";
import { getP, selectTarget, setP, useP } from "./store";
import "./prioritize.css";

const fmt = (n: number | undefined | null) => (n == null ? "–" : Math.round(n).toLocaleString("en-US"));
const DOMAIN_LABEL: Record<string, string> = {
  exterior: "Exterior", interior: "Interior & comfort", powertrain: "Powertrain & charging", chassis: "Chassis & dynamics",
  assist: "Driver assistance", digital: "Infotainment & digital", variants: "Variants & packages", quality: "Design & quality",
};
const DOMAIN_ORDER = Object.keys(DOMAIN_LABEL);
const MARKET_NAME: Record<string, string> = { US: "US", EU: "Europe", CN: "China", JP: "Japan", RoW: "Rest of world" };

export function PrioritizeHud() {
  const pd = usePrioritize();
  const { data } = pd;
  const activity = useActivity("prioritize");
  const line = useView((s) => s.line);
  const lines = useMemo(() => linesOf(data), [data]);
  const markets = useMemo(() => marketsOf(data, line), [data, line]);
  const stored = useP((s) => s.market[line]);
  const market = stored && markets.includes(stored) ? stored : markets[0] ?? "";
  const selected = useP((s) => s.selected);
  const view = useP((s) => s.view);
  useP((s) => s.pending);
  useP((s) => s.pendingProposals);

  // page 4 continues on the car: page 3's stage is the car, nothing of page 3 stays open
  useEffect(() => { setView({ stage: DEF_STAGES[DEF_STAGES.length - 1], auto: false, selected: null, hover: null, hoverPos: null, bundle: null }); }, []);
  // a line without prioritized targets falls back to one that has them
  useEffect(() => { if (lines.length && !lines.includes(line)) setView({ line: (lines.includes("5 Series") ? "5 Series" : lines[0]) as LineName }); }, [lines, line]);

  const targets = useMemo(() => data.targets.filter((t) => t.line === line && t.market === market), [data, line, market]);
  const sel = selected ? targets.find((t) => t.key === selected) ?? null : null;

  // the list and inspector sit behind the Priorities pill; picking a column opens it, closing it deselects
  const top = useTopPanel();
  const showPanel = top === "priorities";
  useEffect(() => { if (selected && getTopPanel() !== "priorities") setTopPanel("priorities"); }, [selected]);
  useEffect(() => { if (top !== "priorities" && getP().selected) selectTarget(null); }, [top]);
  useEffect(() => { if (selected && !data.targets.some((t) => t.key === selected && t.line === line)) selectTarget(null); }, [selected, line, data]);

  const setMarket = (m: string) => setP((s) => ({ market: { ...s.market, [line]: m } }));
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.metaKey || e.ctrlKey || e.altKey || (e.target instanceof HTMLElement && /^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName))) return;
      if (e.key === "Escape") {
        const s = getP();
        if (s.selected) selectTarget(null);
        else if (s.bundle) setP({ bundle: null });
        else if (s.view === "matrix") setP({ view: "skyline" });
        else setTopPanel((t) => (t === "priorities" ? null : t));
      }
      // [ and ] step through the line's markets (the arrow keys belong to the checkpoints)
      if (e.key === "[" || e.key === "]") {
        const i = markets.indexOf(market) + (e.key === "]" ? 1 : -1);
        if (i >= 0 && i < markets.length) setMarket(markets[i]);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  });
  useEffect(() => () => setP({ hover: null, hoverPos: null }), []);

  /* readout */
  const counts = { Must: 0, Should: 0, Could: 0 } as Record<Band, number>;
  for (const t of targets) counts[shownBand(t)]++;
  const props = openProposals(data).filter((p) => p.line === line && p.market === market);
  const joint = new Set(targets.flatMap((t) => parseFlags(t).filter((f) => f.kind === "choose_jointly").map((f) => [t.key, f.partner].sort().join("~")))).size;
  const blocked = targets.filter(isBlocked).length;
  const disagree = disagreements(data, line);
  const confirmed = targets.filter((t) => pmBand(t)).length;
  // the matrix hangs right under this corner, however tall it is (sample note, wrapped controls)
  const hudRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const el = hudRef.current;
    if (!el) return;
    const put = () => document.documentElement.style.setProperty("--phud-bottom", `${Math.round(el.getBoundingClientRect().bottom)}px`);
    put();
    const ro = new ResizeObserver(put);
    ro.observe(el);
    window.addEventListener("resize", put);
    return () => { ro.disconnect(); window.removeEventListener("resize", put); };
  }, []);

  return (
    <>
      <div className="hud-tl phud" ref={hudRef}>
        {/* the band numbers stay narrow enough to sit left of the top bar, like pages 1–3; the rest goes under them */}
        <dl className="preadout" aria-label={`Priorities for ${line} in ${market}`}>
          {BANDS.map((b) => (
            <div key={b} className="preadout-band">
              <dt className="label"><BandMark band={b} color="var(--ink)" size="sm" />{b}</dt>
              <dd><span className="num">{counts[b]}</span></dd>
            </div>
          ))}
        </dl>
        <dl className="pstats" aria-label="Open items">
          <div><dt className="label">proposals</dt><dd className="num">{props.length}</dd></div>
          <div><dt className="label">choose jointly</dt><dd className="num">{joint}</dd></div>
          <div><dt className="label">blocked</dt><dd className="num">{blocked}</dd></div>
          {markets.length > 1 && <div><dt className="label">markets disagree</dt><dd className="num">{disagree.size}</dd></div>}
        </dl>
        <p className="pnote label">{targets.length} targets · {confirmed} confirmed by the PM · weights {String(data.weights?.scheme ?? "prio-v1")} · market weight {data.labels?.market_weight ?? "stylized (Q-015)"}</p>
        <div className="pcontrols">
          <div className="dseg" role="radiogroup" aria-label="Car line">
            {lines.map((l) => <button key={l} role="radio" aria-checked={line === l} onClick={() => setView({ line: l as LineName })}>{l}</button>)}
          </div>
          <div className="dseg pmarkets" role="radiogroup" aria-label="Market">
            <span className="dseg-name label">Market</span>
            {markets.map((m) => <button key={m} role="radio" aria-checked={market === m} onClick={() => setMarket(m)} title={MARKET_NAME[m] ?? m}>{m}</button>)}
          </div>
          <div className="dseg" role="radiogroup" aria-label="View">
            <button role="radio" aria-checked={view === "skyline"} onClick={() => setP({ view: "skyline" })}>Skyline</button>
            <button role="radio" aria-checked={view === "matrix"} onClick={() => setP({ view: "matrix" })}>Matrix</button>
          </div>
        </div>
        {pd.sample && <p className="dsample" role="status"><b>Sample data</b> {pd.why}. Live priorities replace it as soon as the stage has run.</p>}
      </div>

      {view === "matrix" && <Matrix pd={pd} line={line} markets={markets} market={market} onMarket={setMarket} />}
      {showPanel && (sel ? <Inspector key={tid(sel)} pd={pd} t={sel} markets={markets} onMarket={setMarket} /> : <RankedList pd={pd} targets={targets} line={line} market={market} />)}
      <TargetHover pd={pd} line={line} market={market} />
      <Dock mode="prioritize" sel={null} guide={<PrioritizeGuide sel={sel} view={view} />} agent={<AgentPanel layer="prioritize" />} running={!!activity.data?.running} />
    </>
  );
}

/* --------------------------------------------------------------------------------------------- ranked list */
function RankedList({ pd, targets, line, market }: { pd: PrioData; targets: Target[]; line: string; market: string }) {
  const selected = useP((s) => s.selected);
  const sorted = [...targets].sort((a, b) => b.score - a.score);
  const proposals = new Map(openProposals(pd.data).filter((p) => p.line === line && p.market === market).map((p) => [p.key, p]));
  return (
    <nav className="dlist plist" id="priorities-panel" aria-label="Priorities">
      <p className="dlist-head"><span className="sheet-layer">Priorities · {line} · {market}</span><span className="label">Score</span></p>
      {BANDS.map((b) => {
        const items = sorted.filter((t) => shownBand(t) === b);
        if (!items.length) return null;
        return (
          <section key={b}>
            <h3 className="dlist-domain plist-band"><BandMark band={b} color="var(--ink-2)" size="sm" />{b}<span>{items.length}</span></h3>
            <ul>
              {items.map((t) => {
                const pm = pmBand(t);
                const flags = parseFlags(t);
                const p = proposals.get(t.key);
                const d = t.prev ? t.score - t.prev.score : 0;
                return (
                  <li key={t.key}>
                    <button className="dlist-row plist-row" aria-current={selected === t.key ? "true" : undefined}
                            onClick={() => selectTarget(selected === t.key ? null : t.key)}
                            onPointerEnter={() => setP({ hover: t.key })} onPointerLeave={() => setP({ hover: null })}>
                      <span className="plist-rank">{t.rank}</span>
                      <BandMark band={shownBand(t)} color={domainColor(t.domain)} />
                      <span className="dlist-title">{t.title}</span>
                      <span className="plist-tags">
                        {pm && <span className="ptag-pm">PM</span>}
                        {isBlocked(t) && <span className="psky-blocked" title="Brand fit blocks approval" />}
                        {flags.some((f) => f.kind === "choose_jointly") && <span className="ptag" data-dashed="" title="Choose jointly">joint</span>}
                        {p && <span className="ptag" title={`AI proposes ${p.proposed_band}`}>→ {p.proposed_band}</span>}
                        <span className="plist-conf" title="Confidence">{t.confidence.level}</span>
                      </span>
                      <span className="dlist-val">{fmt(t.score)}{Math.abs(d) >= 1 && <Arrow d={d} />}</span>
                    </button>
                  </li>
                );
              })}
            </ul>
          </section>
        );
      })}
    </nav>
  );
}

/* --------------------------------------------------------------------------------------------- hover */
function TargetHover({ pd, line, market }: { pd: PrioData; line: string; market: string }) {
  const hover = useP((s) => s.hover);
  const pos = useP((s) => s.hoverPos);
  const selected = useP((s) => s.selected);
  if (!hover || !pos || hover === selected) return null;
  const t = pd.data.targets.find((x) => x.key === hover && x.line === line && x.market === market);
  if (!t) return null;
  const left = Math.min(pos.x + 16, window.innerWidth - 336), top = Math.min(pos.y + 16, window.innerHeight - 140);
  return (
    <div className="hovercard" style={{ left, top }} role="tooltip">
      <p>{t.title}</p>
      <div className="hovercard-meta">
        <BandMark band={shownBand(t)} color={domainColor(t.domain)} size="sm" /><span>{shownBand(t)} · {fmt(t.score)}</span>
        <span>#{t.rank} in {line} · {market}</span><span>{t.confidence.level}</span>
      </div>
      <div className="hovercard-meta"><span>{DOMAIN_LABEL[t.domain] ?? t.domain}</span>{t.prev && <span>JAN {fmt(t.prev.score)} → JUL {fmt(t.score)}</span>}</div>
    </div>
  );
}

/* --------------------------------------------------------------------------------------------- matrix */
// Rows grouped by domain, one column per market of the line; each cell the band mark (domain hue) with its score,
// an arrow where JAN → JUL moved it, a blue ring where the PM confirmed it. A white tick marks rows whose band differs
// between markets.
function Matrix({ pd, line, markets, market, onMarket }: { pd: PrioData; line: string; markets: string[]; market: string; onMarket: (m: string) => void }) {
  const { position } = useCheckpoint();
  const selected = useP((s) => s.selected);
  const hover = useP((s) => s.hover);
  const onLine = pd.data.targets.filter((t) => t.line === line);
  const cell = new Map(onLine.map((t) => [tid(t), t]));
  const reqs = [...new Map(onLine.map((t) => [t.key, t])).values()];
  const best = (k: string) => Math.max(...onLine.filter((t) => t.key === k).map((t) => t.score));
  const groups = DOMAIN_ORDER.map((d) => ({ d, items: reqs.filter((r) => r.domain === d).sort((a, b) => best(b.key) - best(a.key)) })).filter((g) => g.items.length);
  const disagree = disagreements(pd.data, line);
  const props = new Set(openProposals(pd.data).map((p) => `${p.key}|${p.line}|${p.market}`));
  return (
    <section className="pmatrix" aria-label={`Market by requirement, ${line}`}>
      <header className="pmatrix-head">
        <span className="sheet-layer">Market × requirement · {line}</span>
        <span className="pmatrix-legend label">
          <span><BandMark band="Must" color="var(--ink-2)" size="sm" />Must</span><span><BandMark band="Should" color="var(--ink-2)" size="sm" />Should</span>
          <span><BandMark band="Could" color="var(--ink-2)" size="sm" />Could</span><span><i className="pmatrix-pm" />PM confirmed</span>
          {position > 1 && <span>▲▼ since JAN</span>}<span><i className="pmatrix-dis" />markets disagree</span>
        </span>
      </header>
      <div className="pmatrix-grid" style={{ ["--m" as string]: markets.length }}>
        <div className="pmatrix-row pmatrix-cols" aria-hidden>
          <span />
          {markets.map((m) => <button key={m} className="pmatrix-mkt" aria-pressed={m === market} onClick={() => onMarket(m)}>{m}</button>)}
          <span />
        </div>
        {groups.map(({ d, items }) => (
          <div key={d} className="pmatrix-group">
            <h3 className="dlist-domain"><i style={{ background: domainColor(d) }} aria-hidden />{DOMAIN_LABEL[d] ?? d}<span>{items.length}</span></h3>
            {items.map((r) => (
              <div key={r.key} className="pmatrix-row" data-on={selected === r.key ? "" : undefined} data-hover={hover === r.key ? "" : undefined}
                   onPointerEnter={() => setP({ hover: r.key })} onPointerLeave={() => setP({ hover: null })}>
                <button className="pmatrix-title" onClick={() => selectTarget(selected === r.key ? null : r.key)}>{r.title}</button>
                {markets.map((m) => {
                  const t = cell.get(`${r.key}|${line}|${m}`);
                  if (!t) return <span key={m} className="pmatrix-cell" data-empty="">·</span>;
                  const d = t.prev && position > 1 ? t.score - t.prev.score : 0;
                  const b = shownBand(t);
                  return (
                    <button key={m} className="pmatrix-cell" data-current={m === market ? "" : undefined} title={`${m}: ${b} · ${fmt(t.score)}`}
                            onClick={() => { onMarket(m); selectTarget(r.key); }}>
                      <BandMark band={b} color={domainColor(t.domain)} pm={!!pmBand(t)} />
                      <span className="pmatrix-score">{fmt(t.score)}</span>
                      {(Math.abs(d) >= 3 || (t.prev && t.prev.band !== t.band && position > 1)) && <Arrow d={d} />}
                      {props.has(tid(t)) && <span className="pmatrix-prop" title="Open AI proposal">P</span>}
                    </button>
                  );
                })}
                <span className="pmatrix-dis" data-on={disagree.has(r.key) ? "" : undefined} aria-label={disagree.has(r.key) ? "markets disagree" : undefined} />
              </div>
            ))}
          </div>
        ))}
      </div>
    </section>
  );
}

/* --------------------------------------------------------------------------------------------- inspector */
const RUNGS: Rung[] = ["baseline", "threshold", "target", "stretch"];

function Inspector({ pd, t, markets, onMarket }: { pd: PrioData; t: Target; markets: string[]; onMarket: (m: string) => void }) {
  const { data } = pd;
  const { position } = useCheckpoint();
  const detail = useTargetDetail(t, pd);
  const at = bandsAt(data);
  const band = shownBand(t);
  const pm = pmBand(t);
  const [rung, setRung] = useState<Rung | null>(null);
  const cur = t.rung.chosen ?? t.rung.recommended;
  const wi = useWhatIf(t, rung && rung !== cur ? rung : null, pd);
  const flags = parseFlags(t);
  const titleOf = (k: string) => data.targets.find((x) => x.key === k)?.title ?? k;
  const others = markets.map((m) => data.targets.find((x) => x.key === t.key && x.line === t.line && x.market === m) ?? null);
  const disagree = new Set(others.filter(Boolean).map((x) => shownBand(x!))).size > 1;
  const bundle = t.bundle_id ? data.bundles.find((b) => b.id === t.bundle_id) ?? null : null;
  const bundleOn = useP((s) => s.bundle);
  const proposal = openProposals(data).find((p) => p.key === t.key && p.line === t.line && p.market === t.market) ?? null;
  const d = t.prev ? t.score - t.prev.score : 0;
  const gates: [string, keyof Target["gates"]][] = [["Brand fit", "brand"], ["Segment fit", "segment"], ["Market fit", "market"], ["Feasibility", "feasibility"]];

  return (
    <aside className="sheet dsheet psheet" id="priorities-panel" aria-label="Target priority">
      <button className="sheet-close" onClick={() => selectTarget(null)} aria-label="Close"><X size={16} /></button>
      <header className="sheet-head">
        <span className="sheet-layer"><BandMark band={band} color={domainColor(t.domain)} size="sm" />{DOMAIN_LABEL[t.domain] ?? t.domain} · {t.line} · {t.market}</span>
        <p className="sheet-what">One requirement in one market. The AI scores it and proposes a band; the PM decides.</p>
      </header>
      <h2 className="sheet-title">{t.title}</h2>

      <div className="pfigure">
        <span className="pfigure-num">{fmt(t.score)}</span>
        <span className="pfigure-side">
          <span className="pfigure-band">{band}{pm && <span className="ptag-pm">PM</span>}{!pm && <span className="ptag">AI proposal</span>}</span>
          <span className="label">#{t.rank} of {data.targets.filter((x) => x.line === t.line && x.market === t.market).length} in {t.line} · {t.market} · {t.confidence.level} confidence</span>
          {t.prev && position > 1 && <span className="label">JAN {fmt(t.prev.score)} {t.prev.band} → JUL {fmt(t.score)} {t.band} <Arrow d={Math.abs(d) >= 1 ? d : 0} /></span>}
        </span>
      </div>

      {markets.length > 1 && (
        <div className="dblock">
          <span className="label">Across {t.line} markets{disagree ? " · markets disagree" : ""}</span>
          <div className="pmkts">
            {markets.map((m, i) => {
              const o = others[i];
              return (
                <button key={m} className="pmkt" aria-pressed={m === t.market} disabled={!o} onClick={() => o && onMarket(m)}>
                  <span className="pmkt-m">{m}</span>
                  {o ? <><BandMark band={shownBand(o)} color={domainColor(o.domain)} pm={!!pmBand(o)} /><span className="pmkt-s">{fmt(o.score)}</span></> : <span className="pmkt-s">not targeted</span>}
                </button>
              );
            })}
          </div>
        </div>
      )}

      <div className="dblock">
        <span className="label">How the score adds up</span>
        <Waterfall t={t} at={at} band={band} whatIf={wi.data ? { score: wi.data.score, band: wi.data.band } : null} />
        <p className="dnote"><span className="label">Rationale</span>{t.rationale}</p>
      </div>

      <div className="dblock">
        <span className="label">Gates</span>
        <ul className="pgates">
          {gates.map(([name, k]) => {
            const r = gateResult(t.gates?.[k]);
            return (
              <li key={k} data-r={r}>
                <GateMark result={r} /><span className="pgates-name">{name}</span><span className="pgates-r">{r}</span>
                {gateWhy(t.gates?.[k]) && <span className="pgates-why">{gateWhy(t.gates?.[k])}</span>}
              </li>
            );
          })}
        </ul>
        {isBlocked(t) && <p className="pblock">Brand fit fails: a PM approval needs an override with a rationale (D-008).</p>}
      </div>

      <div className="dblock">
        <div className="dlinks-head"><span className="label">Ladder rung · what if</span><span className="label">AI recommends {t.rung.recommended}{t.rung.chosen ? ` · PM chose ${t.rung.chosen}` : ""}</span></div>
        <div className="dseg prungs" role="radiogroup" aria-label="What-if rung">
          {RUNGS.map((r) => (
            <button key={r} role="radio" aria-checked={(rung ?? cur) === r} onClick={() => setRung(r === cur ? null : r)}>
              {r}{r === cur ? " ·" : ""}
            </button>
          ))}
        </div>
        {rung && rung !== cur && (
          wi.data ? (
            <div className="pwhatif">
              <p><span className="num">{fmt(t.score)}</span> → <span className="num">{fmt(wi.data.score)}</span>
                <span className="label"> {band === wi.data.band ? `stays ${band}` : `${band} → ${wi.data.band}`} · not stored</span></p>
              {wi.data.exposures.length > 0 ? (
                <ul className="drail">{wi.data.exposures.map((x, i) => <li key={i}><b>{x.note ?? `exposure via ${x.via}`}</b> · {x.title ?? titleOf(x.key)}</li>)}</ul>
              ) : <p className="label">No linked requirement exposed.</p>}
            </div>
          ) : wi.error ? <p className="derror">What-if unavailable: {wi.error.message}</p> : <p className="label">Recomputing…</p>
        )}
      </div>

      {bundle && (
        <div className="dblock">
          <div className="dlinks-head">
            <span className="label">Bundle · prioritized together</span>
            <button className="dtext" aria-pressed={bundleOn === bundle.id} onClick={() => setP({ bundle: bundleOn === bundle.id ? null : bundle.id })}>{bundleOn === bundle.id ? "Hide bundle" : "Show bundle"}</button>
          </div>
          <ul className="pmembers">
            {bundle.keys.map((k) => {
              const o = data.targets.find((x) => x.key === k && x.line === t.line && x.market === t.market);
              return (
                <li key={k}>
                  {o ? <button className="dlink-other" onClick={() => selectTarget(k)}><BandMark band={shownBand(o)} color={domainColor(o.domain)} size="sm" />{o.title}<span className="pmembers-s">{fmt(o.score)}</span></button>
                    : <span className="dlink-other pmembers-off">{titleOf(k)} <span className="label">not targeted in {t.market}</span></span>}
                </li>
              );
            })}
          </ul>
          {bundle.reason && <p className="label">{bundle.reason}; the bundle shares its strongest member's band.</p>}
        </div>
      )}

      {flags.filter((f) => f.kind !== "brand_blocked").length > 0 && (
        <div className="dblock">
          <span className="label">Flags</span>
          <ul className="pflags">
            {flags.filter((f) => f.kind !== "brand_blocked").map((f) => (
              <li key={f.raw}>
                <span className="ptag" data-dashed={f.kind === "choose_jointly" ? "" : undefined}>{flagLabel(f.kind)}{f.via ? ` · ${f.via}` : ""}</span>
                {f.kind === "choose_jointly" && f.partner && <button className="dlink-other" onClick={() => selectTarget(f.partner!)}>with {titleOf(f.partner)}</button>}
                {f.kind === "bundle_band" && <span className="label">scored {f.band} on its own</span>}
                {f.kind === "borrowed_voice" && <span className="label">no own-market comments; × 0.5 and capped (D-038)</span>}
              </li>
            ))}
          </ul>
        </div>
      )}

      {(detail?.history?.length ?? 0) > 0 && (
        <div className="dblock">
          <span className="label">History</span>
          <ol className="phistory">
            {detail!.history.map((h) => (
              <li key={h.checkpoint}>
                <span className="phistory-cp">{CP_LABEL[h.checkpoint] ?? h.checkpoint}</span>
                <BandMark band={h.band} color={domainColor(t.domain)} size="sm" />
                <span className="phistory-s">{fmt(h.score)}</span>
                <span className="label">{h.band}{h.rung ? ` · ${h.rung}` : ""}{h.confirmed ? ` · PM ${h.confirmed}` : ""}</span>
              </li>
            ))}
          </ol>
        </div>
      )}

      {proposal && <ProposalBlock pd={pd} p={proposal} />}
      <DecisionBlock pd={pd} t={t} />
    </aside>
  );
}

function ProposalBlock({ pd, p }: { pd: PrioData; p: Proposal }) {
  const verdict = useProposalVerdict(pd);
  const [open, setOpen] = useState<"accept" | "reject" | null>(null);
  const [why, setWhy] = useState("");
  const deltas = Object.entries(p.factor_delta ?? {}).filter(([, v]) => v);
  const down = deltas.reduce((s, [, v]) => s + v, 0) < 0;
  return (
    <div className="dblock pproposal">
      <span className="label">AI proposal · JAN → JUL</span>
      <p className="pproposal-line"><BandMark band={p.old_band} color="var(--ink-2)" size="sm" />{p.old_band ?? "–"} <span aria-hidden>→</span> <BandMark band={p.proposed_band} color="var(--ink)" size="sm" />{p.proposed_band}
        <span className="label"> · {CAUSE_LABEL[p.cause] ?? p.cause}{p.cause === "area_strengthened" && down ? " (weaker)" : ""}</span></p>
      {deltas.length > 0 && <ul className="drail">{deltas.map(([k, v]) => <li key={k}>{factorLabel(k)} <b>{v > 0 ? "+" : "−"}{Math.abs(v)} pts</b></li>)}</ul>}
      {open ? (
        <form className="ladder-choose" onSubmit={(e) => { e.preventDefault(); if (why.trim().length >= 5) { verdict.mutate({ p, verdict: open, rationale: why.trim() }); setOpen(null); setWhy(""); } }}>
          <textarea rows={2} value={why} onChange={(e) => setWhy(e.target.value)} autoFocus placeholder={`Why ${open} this proposal? (required)`} aria-label="Rationale" />
          <div className="ladder-actions">
            <button type="submit" className="dbtn primary" disabled={why.trim().length < 5 || verdict.isPending}>{open === "accept" ? `Accept → ${p.proposed_band}` : "Reject"}</button>
            <button type="button" className="dbtn" onClick={() => setOpen(null)}>Cancel</button>
          </div>
        </form>
      ) : (
        <div className="dlink-actions">
          <button className="dtext" onClick={() => setOpen("accept")}>Accept</button>
          <button className="dtext" onClick={() => setOpen("reject")}>Reject</button>
        </div>
      )}
      {verdict.isError && <p className="derror">Not saved: {(verdict.error as Error).message}</p>}
    </div>
  );
}

function DecisionBlock({ pd, t }: { pd: PrioData; t: Target }) {
  const decide = useDecision(pd);
