/* Page 4 weights panel: the right-hand column (page 3's .dlist field, one top-right panel at a time). Numerals lead,
   labels at micro size, neutral ink only: blue stays the PM's confirmed band. The current value is an ink-3 tick on
   the track once the slider has moved away from it. */
.pweights { width: min(400px, calc(100vw - 32px)); gap: 16px; }
.pweights .audit-close { top: 10px; right: 16px; }
.pweights-open span { margin-left: 6px; color: var(--ink-3); font-variant-numeric: tabular-nums; }
.dseg .pweights-open[aria-expanded="true"] { color: var(--ink); background: rgba(255, 255, 255, 0.09); }

.pw-group { display: grid; gap: 4px; }
.pw-row { display: grid; grid-template-columns: 118px 1fr 26px 34px; align-items: center; gap: 10px; min-height: 26px; }
.pw-label { font-size: 13px; color: var(--ink-2); display: grid; line-height: 1.2; }
.pw-label i { font-style: normal; font-size: var(--t-micro); color: var(--ink-3); }
.pw-row[data-moved] .pw-label { color: var(--ink); }
.pw-val { font-size: 15px; color: var(--ink); text-align: right; font-stretch: 118%; font-weight: 300; font-variant-numeric: tabular-nums; }
.pw-share { font-size: var(--t-micro); color: var(--ink-3); text-align: right; font-variant-numeric: tabular-nums; }
.pw-row:not(:has(.pw-share)) { grid-template-columns: 118px 1fr 26px 34px; }

.pw-track { position: relative; height: 18px; display: grid; align-items: center; }
.pw-track input[type="range"] { -webkit-appearance: none; appearance: none; width: 100%; height: 18px; margin: 0; background: transparent; cursor: pointer; }
.pw-track input[type="range"]:disabled { cursor: default; opacity: 0.4; }
.pw-track input[type="range"]::-webkit-slider-runnable-track { height: 2px; border-radius: 1px; background: var(--hair-2); }
.pw-track input[type="range"]::-moz-range-track { height: 2px; border-radius: 1px; background: var(--hair-2); }
.pw-track input[type="range"]::-webkit-slider-thumb { -webkit-appearance: none; width: 12px; height: 12px; margin-top: -5px; border-radius: 50%; background: var(--ink); border: 0; }
.pw-track input[type="range"]::-moz-range-thumb { width: 12px; height: 12px; border-radius: 50%; background: var(--ink); border: 0; }
.pw-track input[type="range"]:focus-visible { outline: none; }
.pw-track input[type="range"]:focus-visible::-webkit-slider-thumb { box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.25); }
.pw-was { position: absolute; top: 4px; width: 1.4px; height: 10px; margin-left: -0.7px; background: var(--ink-3); pointer-events: none; }

.pw-preview { display: grid; gap: 6px; padding-top: 10px; border-top: 1px solid var(--hair); min-height: 44px; }
.pw-readout { display: flex; gap: 26px; transition: opacity var(--fast); }
.pw-readout[data-busy] { opacity: 0.55; }
.pw-readout > div { display: grid; gap: 4px; }
.pw-readout .num { font-size: 28px; color: var(--ink); }
.pw-moves { display: flex; flex-wrap: wrap; gap: 4px 14px; font-size: var(--t-label); color: var(--ink-2); }
.pw-moves b { color: var(--ink); font-weight: 400; font-variant-numeric: tabular-nums; }
.pw-err { font-size: var(--t-label); color: var(--ink); }

.pw-hist ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 1px; }
.pw-hrow {
  width: calc(100% + 16px); margin-left: -8px; padding: 4px 8px; border-radius: 6px; text-align: left; display: grid;
  grid-template-columns: 36px auto 1fr; gap: 10px; align-items: baseline; transition: background var(--fast);
}
.pw-hrow:hover { background: rgba(255, 255, 255, 0.05); }
.pw-hrow[aria-current="true"] .pw-hv { color: var(--ink); }
.pw-hv { font-size: 13px; color: var(--ink-2); font-variant-numeric: tabular-nums; }
.pw-hwho { font-size: var(--t-micro); color: var(--ink-3); white-space: nowrap; }
.pw-hwhy { font-size: var(--t-label); color: var(--ink-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* the HUD's quiet re-scoring state after a PM action */
.prescore { color: var(--ink-2); }
.prescore::before { content: ""; display: inline-block; width: 5px; height: 5px; margin: 0 5px 1px 2px; border-radius: 50%; background: var(--ink-2); animation: prescore 1s var(--ease) infinite alternate; }
@keyframes prescore { from { opacity: 0.25; } to { opacity: 1; } }
@media (prefers-reduced-motion: reduce) { .prescore::before { animation: none; } }

