import { useSyncExternalStore } from "react";
import { api, queryClient } from "@/lib/api";

let busy = false;
const subs = new Set<() => void>();
const setBusy = (v: boolean) => { if (v !== busy) { busy = v; subs.forEach((f) => f()); } };
