export type Rung = "baseline" | "threshold" | "target" | "stretch";
export type ChoosableRung = Exclude<Rung, "baseline">;
export type Relation = "conflicts" | "competes_for" | "enables" | "synergy";
export type Via = "energy" | "mass" | "thermal" | "package" | "attention" | "aero" | "acoustic" | "compute";
/** Track state of a requirement / link; the spec track reports a moved recommended target as "changed". */
export type DefState = TrackState | "changed";

export interface Level {
  value: number | null;
  text: string;
  basis: Basis;
  source_ids: string[];
  note: string;
}

export interface Choice { level: ChoosableRung; rationale: string; actor: string; at: string }

export interface LadderRow {
  line: LineName | string;
  market: string;
  baseline: Level | null;
  threshold: Level;
  target: Level;
  stretch: Level | null;
  recommended: ChoosableRung;
  rationale: string;
  choice?: Choice | null;
}

export interface Metric {
  name: string;
  unit: string;
  direction: "higher" | "lower" | "binary";
  method?: string | null;
  conditions?: string | null;
}

export interface Acceptance { criterion: string; condition: string; pass: string }

export interface Requirement {
  key: string;
  version: number;
  area_key: string;
  area_title: string;
  title: string;
  statement: string;
  domain: string;
  aspects: string[];
  zones: string[];
  lines: string[];
  markets: string[];
  decision_type: string | null;
  today_status: string | null;
  horizon: string | null;
  horizon_year: number | null;
  kano: string | null;
  state: DefState | null;
  change_note: string | null;
  metric: Metric | null;
  acceptance: Acceptance[];
  ladder: LadderRow[];
  gaps: string[];
  assumptions: string[];
  evidence_count: number;
}
    if (q.data?.models && Object.keys(q.data.models).length) fx.models = { ...fx.models, ...q.data.models };
    const why = q.isError ? "Definition API not available" : q.data && !q.data.ready ? "Pipeline has not run at this checkpoint" : "Waiting for the API";
    return { data: fx, sample: true, why, pending: q.isPending };
  }, [q.data, q.isError, q.isPending, cp]);
}

export function useRequirementDetail(key: string | null, def: DefData) {
  const { cp } = useCheckpoint();
  const live = !def.sample;
  const q = useQuery({
    queryKey: ["definition-req", key, cp],
    queryFn: () => api.get<RequirementDetail>(`/api/definition/requirement/${encodeURIComponent(key!)}?cp=${cp}`),
    enabled: !!key && live, retry: false, staleTime: 15_000,
  });
  return useMemo(() => {
    if (!key) return null;
    if (live && q.data) return q.data;
    const r = def.data.requirements.find((x) => x.key === key);
    return r ? (live ? { ...r, evidence: [], facts: [], area: null, history: [] } as RequirementDetail : fixtureDetail(r)) : null;
  }, [key, live, q.data, def.data]);
}

