content.content:
.pmatrix {
  /* on the far left, under the HUD and above the dock's pills, so the car in the centre stays clear; clear of the
     right panel too */
  position: fixed; left: var(--edge); top: calc(var(--phud-bottom, 248px) + 14px); bottom: 96px; z-index: 13; width: min(560px, calc(100vw - 2 * var(--edge) - 460px));
  overflow-y: auto; padding: 16px 22px 24px; display: grid; gap: 12px; align-content: start;
  background: var(--field); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  --feather: linear-gradient(to right, transparent, #000 16px, #000 calc(100% - 16px), transparent), linear-gradient(to bottom, transparent, #000 12px, #000 calc(100% - 22px), transparent);
  -webkit-mask-image: var(--feather); mask-image: var(--feather); -webkit-mask-composite: source-in; mask-composite: intersect;
  animation: sheet-in var(--med) var(--ease);
}
.pmatrix-head { display: flex; justify-content: space-between; align-items: baseline; gap: 16px; flex-wrap: wrap; }
.pmatrix-legend { display: inline-flex; gap: 14px; flex-wrap: wrap; align-items: flex-end; }
.pmatrix-legend > span { display: inline-flex; align-items: flex-end; gap: 5px; }
.pmatrix-pm { display: inline-block; width: 10px; height: 2px; margin-bottom: 2px; background: var(--sweep-hi); box-shadow: 0 0 0 2px var(--sweep-wash); }
.pmatrix-grid { display: grid; gap: 12px; }
.pmatrix-group { display: grid; gap: 1px; }
.pmatrix-row { display: grid; grid-template-columns: minmax(0, 1fr) repeat(var(--m), 64px) 14px; align-items: center; gap: 0 6px; min-height: 28px; border-radius: 6px; padding: 0 6px; margin: 0 -6px; transition: background var(--fast); }
.pmatrix-row[data-hover], .pmatrix-row[data-on] { background: rgba(255, 255, 255, 0.05); }
.pmatrix-cols { position: sticky; top: -16px; z-index: 1; background: rgba(0, 0, 0, 0.9); min-height: 30px; }
.pmatrix-mkt { height: 24px; border-radius: 99px; font-size: var(--t-label); font-weight: 600; letter-spacing: 0.08em; color: var(--ink-3); transition: color var(--fast), background var(--fast); }
.pmatrix-mkt:hover { color: var(--ink); }
4:.dock {
5-  position: fixed; left: var(--edge); bottom: calc(var(--edge) + env(safe-area-inset-bottom, 0px)); z-index: 12;
6-  width: 300px; display: grid; gap: 12px; justify-items: start;
7-}
--

